#define TAG "CURRENT_AP"
#define AP_SSID "TCU-CURRENT"
#define AP_PASSWORD "tcu-current"

static const char *dashboard_html =
    "<!doctype html><html><head><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>TCU Current</title>"
    "<style>body{font-family:Arial;background:#101820;color:#fff;text-align:center;padding:24px}.card{max-width:440px;margin:auto;background:#1d2a35;border-radius:16px;padding:24px}.current{font-size:64px;color:#45d483;font-weight:bold;margin:24px 0 4px}.unit{font-size:20px;color:#bbc6cc}.details{text-align:left;background:#101820;border-radius:10px;padding:14px;margin-top:22px;line-height:1.9}.ok{color:#45d483}.bad{color:#ff6868}</style></head>"
    "<body><div class=card><h1>TCU Current</h1><div id=current class=current>--</div><div class=unit>A</div><p id=status>Connecting...</p>"
    "<div class=details>ADC voltage: <span id=adc>--</span> mV<br>Raw ADC: <span id=raw>--</span><br>Raw current: <span id=rawi>--</span> A<br>Offset: <span id=offset>--</span> A</div></div>"
    "<script>async function update(){try{const d=await (await fetch('/api/current',{cache:'no-store'})).json();current.textContent=d.current_a.toFixed(3);adc.textContent=d.adc_mv.toFixed(2);raw.textContent=d.raw_adc;rawi.textContent=d.raw_current_a.toFixed(3);offset.textContent=d.offset_a.toFixed(3);status.textContent=d.valid?'Live':'Read failed';status.className=d.valid?'ok':'bad'}catch(e){status.textContent='Connection failed';status.className='bad'}}update();setInterval(update,500)</script></body></html>";

static esp_err_t root_handler(httpd_req_t *req)
{
    httpd_resp_set_type(req, "text/html");
    return httpd_resp_send(req, dashboard_html, HTTPD_RESP_USE_STRLEN);
}

static esp_err_t current_handler(httpd_req_t *req)
{
    trike_sensor_data_t data = {0};
    float current_a = 0.0f;
    esp_err_t ret = trike_sensors_read_current(&data, &current_a);
    float raw_current_a = 0.0f;
    if (ret == ESP_OK) {
        raw_current_a = (data.adc_mv_current - BOARD_CURRENT_VREF_MV) /
                        (BOARD_CURRENT_SENSE_GAIN *
                         trike_sensors_get_shunt_ohms() * 1000.0f);
    }

    char json[256];
    int len = snprintf(json, sizeof(json),
                       "{\"valid\":%s,\"current_a\":%.6f,\"adc_mv\":%.3f,\"raw_adc\":%d,\"raw_current_a\":%.6f,\"offset_a\":%.6f}",
                       ret == ESP_OK ? "true" : "false",
                       current_a, data.adc_mv_current, data.raw_current,
                       raw_current_a, data.current_offset_applied_a);
    if (len < 0 || len >= (int)sizeof(json)) {
        httpd_resp_set_status(req, "500 Internal Server Error");
        return httpd_resp_sendstr(req, "{\"error\":\"response too large\"}");
    }
    httpd_resp_set_type(req, "application/json");
    httpd_resp_set_hdr(req, "Cache-Control", "no-store");
    return httpd_resp_send(req, json, len);
}

static void start_access_point(void)
{
    ESP_ERROR_CHECK(esp_netif_init());
    ESP_ERROR_CHECK(esp_event_loop_create_default());
    esp_netif_create_default_wifi_ap();

    wifi_init_config_t init_cfg = WIFI_INIT_CONFIG_DEFAULT();
    ESP_ERROR_CHECK(esp_wifi_init(&init_cfg));

    wifi_config_t ap_cfg = {0};
    memcpy(ap_cfg.ap.ssid, AP_SSID, sizeof(AP_SSID) - 1);
    memcpy(ap_cfg.ap.password, AP_PASSWORD, sizeof(AP_PASSWORD) - 1);
    ap_cfg.ap.ssid_len = sizeof(AP_SSID) - 1;
    ap_cfg.ap.channel = 1;
    ap_cfg.ap.max_connection = 4;
    ap_cfg.ap.authmode = WIFI_AUTH_WPA2_PSK;
    ESP_ERROR_CHECK(esp_wifi_set_mode(WIFI_MODE_AP));
    ESP_ERROR_CHECK(esp_wifi_set_config(WIFI_IF_AP, &ap_cfg));
    ESP_ERROR_CHECK(esp_wifi_start());
    ESP_LOGI(TAG, "AP started: SSID=%s password=%s dashboard=http://192.168.4.1/", AP_SSID, AP_PASSWORD);
}

static void start_http_server(void)
{
    httpd_config_t config = HTTPD_DEFAULT_CONFIG();
    httpd_handle_t server = NULL;
    ESP_ERROR_CHECK(httpd_start(&server, &config));

    httpd_uri_t root = {.uri = "/", .method = HTTP_GET, .handler = root_handler};
    httpd_uri_t current = {.uri = "/api/current", .method = HTTP_GET, .handler = current_handler};
    ESP_ERROR_CHECK(httpd_register_uri_handler(server, &root));
    ESP_ERROR_CHECK(httpd_register_uri_handler(server, &current));
}

void app_main(void)
{
    esp_err_t ret = nvs_flash_init();
    if (ret == ESP_ERR_NVS_NO_FREE_PAGES || ret == ESP_ERR_NVS_NEW_VERSION_FOUND) {
        ESP_ERROR_CHECK(nvs_flash_erase());
        ret = nvs_flash_init();
    }
    ESP_ERROR_CHECK(ret);
    ESP_ERROR_CHECK(trike_sensors_init());
    start_access_point();
    start_http_server();
}
