#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include "freertos/FreeRTOS.h"
#include "esp_log.h"
#include "esp_err.h"
#include "esp_wifi.h"
#include "esp_event.h"
#include "esp_netif.h"
#include "esp_http_server.h"
#include "nvs_flash.h"
#include "nvs.h"
#include "esp_adc/adc_oneshot.h"
#include "esp_adc/adc_cali.h"
#include "esp_adc/adc_cali_scheme.h"

#define TAG "CURRENT_AP"
#define CURRENT_GPIO GPIO_NUM_5
#define CURRENT_CHANNEL ADC_CHANNEL_4
#define ADC_SAMPLES 64
#define AP_SSID "TCU-CURRENT"
#define AP_PASSWORD "tcu-current"
#define NVS_NAMESPACE "current_cal"
#define NVS_KEY_VREF "vref_mv"
#define NVS_KEY_GAIN "gain"
#define NVS_KEY_SHUNT "shunt_ohm"
#define NVS_KEY_SCALE "scale"
#define NVS_KEY_OFFSET "offset_a"

static adc_oneshot_unit_handle_t adc_handle;
static adc_cali_handle_t cali_handle;
static bool cali_valid;
static float vref_mv = 1650.0f;
static float sense_gain = 10.0f;
static float shunt_ohm = 0.00025f;
static float scale = 0.97f;
static float offset_a = 0.0f;

static esp_err_t save_calibration(void) {
    nvs_handle_t nvs;
    esp_err_t err = nvs_open(NVS_NAMESPACE, NVS_READWRITE, &nvs);
    if (err != ESP_OK) return err;
    nvs_set_u32(nvs, NVS_KEY_VREF, (uint32_t)(vref_mv * 1000.0f));
    nvs_set_u32(nvs, NVS_KEY_GAIN, (uint32_t)(sense_gain * 1000.0f));
    nvs_set_u32(nvs, NVS_KEY_SHUNT, (uint32_t)(shunt_ohm * 1000000000.0f));
    nvs_set_u32(nvs, NVS_KEY_SCALE, (uint32_t)(scale * 1000000.0f));
    nvs_set_i32(nvs, NVS_KEY_OFFSET, (int32_t)(offset_a * 1000.0f));
    err = nvs_commit(nvs);
    nvs_close(nvs);
    return err;
}

static void load_calibration(void) {
    nvs_handle_t nvs;
    if (nvs_open(NVS_NAMESPACE, NVS_READONLY, &nvs) != ESP_OK) return;
    uint32_t u;
    int32_t i;
    if (nvs_get_u32(nvs, NVS_KEY_VREF, &u) == ESP_OK) vref_mv = u / 1000.0f;
    if (nvs_get_u32(nvs, NVS_KEY_GAIN, &u) == ESP_OK) sense_gain = u / 1000.0f;
    if (nvs_get_u32(nvs, NVS_KEY_SHUNT, &u) == ESP_OK) shunt_ohm = u / 1000000000.0f;
    if (nvs_get_u32(nvs, NVS_KEY_SCALE, &u) == ESP_OK) scale = u / 1000000.0f;
    if (nvs_get_i32(nvs, NVS_KEY_OFFSET, &i) == ESP_OK) offset_a = i / 1000.0f;
    nvs_close(nvs);
}

static esp_err_t read_adc(float *mv, int *raw) {
    int sum = 0;
    for (int n = 0; n < ADC_SAMPLES; n++) {
        int value;
        esp_err_t err = adc_oneshot_read(adc_handle, CURRENT_CHANNEL, &value);
        if (err != ESP_OK) return err;
        sum += value;
    }
    *raw = sum / ADC_SAMPLES;
    if (cali_valid) {
        int calibrated;
        ESP_ERROR_CHECK(adc_cali_raw_to_voltage(cali_handle, *raw, &calibrated));
        *mv = (float)calibrated;
    } else {
        *mv = (float)*raw * 3100.0f / 4095.0f;
    }
    return ESP_OK;
}

static esp_err_t read_current(float *current, float *raw_current, float *mv, int *raw) {
    esp_err_t err = read_adc(mv, raw);
    if (err != ESP_OK) return err;
    *raw_current = (*mv - vref_mv) / (sense_gain * shunt_ohm * 1000.0f);
    *current = (*raw_current * scale) + offset_a;
    return ESP_OK;
}

static esp_err_t send_dashboard(httpd_req_t *req) {
    static const char page[] = "<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'><title>TCU Current</title><style>body{font-family:Arial;background:#101820;color:#fff;text-align:center;padding:18px}.card{max-width:520px;margin:auto;background:#1d2a35;border-radius:16px;padding:22px}.big{font-size:60px;color:#45d483}.row{display:flex;gap:8px;margin:7px 0}.row input{width:100%;padding:8px}.row button{padding:8px}.data{text-align:left;line-height:1.8;margin-top:15px}</style></head><body><div class='card'><h1>TCU Current</h1><div id='i' class='big'>--</div><div>A</div><div id='s'>Connecting...</div><div class='data'>ADC: <span id='mv'>--</span> mV<br>Raw ADC: <span id='raw'>--</span><br>Raw current: <span id='ri'>--</span> A</div><h3>Calibration</h3><div class='row'><input id='vref' type='number' step='0.1' placeholder='Vref mV'><button onclick='setc("vref",vref.value)'>Save</button></div><div class='row'><input id='gain' type='number' step='0.001' placeholder='Sense gain'><button onclick='setc("gain",gain.value)'>Save</button></div><div class='row'><input id='shunt' type='number' step='0.000001' placeholder='Shunt ohms'><button onclick='setc("shunt",shunt.value)'>Save</button></div><div class='row'><input id='scale' type='number' step='0.000001' placeholder='Scale correction'><button onclick='setc("scale",scale.value)'>Save</button></div><button onclick='zero()'>Zero at no current</button><p>Only zero when current is actually 0 A.</p></div><script>async function get(){let d=await (await fetch('/api/current')).json();i.textContent=d.current_a.toFixed(3);mv.textContent=d.adc_mv.toFixed(2);raw.textContent=d.raw_adc;ri.textContent=d.raw_current_a.toFixed(3);s.textContent=d.valid?'Live':'Read failed'}async function setc(k,v){await fetch('/api/calibration?'+k+'='+encodeURIComponent(v));get()}async function zero(){await fetch('/api/calibration?zero=1');get()}get();setInterval(get,500)</script></body></html>";
    httpd_resp_set_type(req, "text/html");
    return httpd_resp_send(req, page, HTTPD_RESP_USE_STRLEN);
}

static esp_err_t api_current(httpd_req_t *req) {
    float current, raw_current, mv; int raw;
    esp_err_t err = read_current(&current, &raw_current, &mv, &raw);
    char json[320];
    int len = snprintf(json, sizeof(json), "{\"valid\":%s,\"current_a\":%.6f,\"raw_current_a\":%.6f,\"adc_mv\":%.3f,\"raw_adc\":%d,\"offset_a\":%.6f,\"vref_mv\":%.3f,\"gain\":%.6f,\"shunt_ohm\":%.9f,\"scale\":%.6f}", err == ESP_OK ? "true" : "false", current, raw_current, mv, raw, offset_a, vref_mv, sense_gain, shunt_ohm, scale);
    httpd_resp_set_type(req, "application/json");
    httpd_resp_set_hdr(req, "Cache-Control", "no-store");
    return httpd_resp_send(req, json, len);
}

static esp_err_t api_calibration(httpd_req_t *req) {
    char query[128];
    size_t len = httpd_req_get_url_query_len(req) + 1;
    if (len > sizeof(query)) return ESP_ERR_INVALID_SIZE;
    if (httpd_req_get_url_query_str(req, query, sizeof(query)) == ESP_OK) {
        char value[32];
        if (httpd_query_key_value(query, "vref", value, sizeof(value)) == ESP_OK) vref_mv = strtof(value, NULL);
        if (httpd_query_key_value(query, "gain", value, sizeof(value)) == ESP_OK) sense_gain = strtof(value, NULL);
        if (httpd_query_key_value(query, "shunt", value, sizeof(value)) == ESP_OK) shunt_ohm = strtof(value, NULL);
        if (httpd_query_key_value(query, "scale", value, sizeof(value)) == ESP_OK) scale = strtof(value, NULL);
        if (httpd_query_key_value(query, "zero", value, sizeof(value)) == ESP_OK) {
            float current, raw_current, mv; int raw;
            if (read_current(&current, &raw_current, &mv, &raw) == ESP_OK) offset_a = -(raw_current * scale);
        }
        if (sense_gain > 0.0f && shunt_ohm > 0.0f && scale > 0.0f) save_calibration();
    }
    httpd_resp_set_type(req, "application/json");
    return httpd_resp_sendstr(req, "{\"saved\":true}");
}

static void start_ap(void) {
    ESP_ERROR_CHECK(esp_netif_init());
    ESP_ERROR_CHECK(esp_event_loop_create_default());
    esp_netif_create_default_wifi_ap();
    wifi_init_config_t init = WIFI_INIT_CONFIG_DEFAULT();
    ESP_ERROR_CHECK(esp_wifi_init(&init));
    wifi_config_t config = {0};
    memcpy(config.ap.ssid, AP_SSID, sizeof(AP_SSID) - 1);
    memcpy(config.ap.password, AP_PASSWORD, sizeof(AP_PASSWORD) - 1);
    config.ap.ssid_len = sizeof(AP_SSID) - 1;
    config.ap.channel = 1;
    config.ap.max_connection = 4;
    config.ap.authmode = WIFI_AUTH_WPA2_PSK;
    ESP_ERROR_CHECK(esp_wifi_set_mode(WIFI_MODE_AP));
    ESP_ERROR_CHECK(esp_wifi_set_config(WIFI_IF_AP, &config));
    ESP_ERROR_CHECK(esp_wifi_start());
}

void app_main(void) {
    esp_err_t err = nvs_flash_init();
    if (err == ESP_ERR_NVS_NO_FREE_PAGES || err == ESP_ERR_NVS_NEW_VERSION_FOUND) { ESP_ERROR_CHECK(nvs_flash_erase()); ESP_ERROR_CHECK(nvs_flash_init()); }
    ESP_ERROR_CHECK(err);
    load_calibration();
    adc_oneshot_unit_init_cfg_t unit = {.unit_id = ADC_UNIT_1, .ulp_mode = ADC_ULP_MODE_DISABLE};
    ESP_ERROR_CHECK(adc_oneshot_new_unit(&unit, &adc_handle));
    adc_oneshot_chan_cfg_t channel = {.atten = ADC_ATTEN_DB_12, .bitwidth = ADC_BITWIDTH_DEFAULT};
    ESP_ERROR_CHECK(adc_oneshot_config_channel(adc_handle, CURRENT_CHANNEL, &channel));
    adc_cali_curve_fitting_config_t cali = {.unit_id = ADC_UNIT_1, .atten = ADC_ATTEN_DB_12, .bitwidth = ADC_BITWIDTH_DEFAULT};
    cali_valid = adc_cali_create_scheme_curve_fitting(&cali, &cali_handle) == ESP_OK;
    start_ap();
    httpd_config_t server_config = HTTPD_DEFAULT_CONFIG();
    httpd_handle_t server;
    ESP_ERROR_CHECK(httpd_start(&server, &server_config));
    httpd_uri_t root = {.uri = "/", .method = HTTP_GET, .handler = send_dashboard};
    httpd_uri_t current = {.uri = "/api/current", .method = HTTP_GET, .handler = api_current};
    httpd_uri_t calibration = {.uri = "/api/calibration", .method = HTTP_GET, .handler = api_calibration};
    ESP_ERROR_CHECK(httpd_register_uri_handler(server, &root));
    ESP_ERROR_CHECK(httpd_register_uri_handler(server, &current));
    ESP_ERROR_CHECK(httpd_register_uri_handler(server, &calibration));
    ESP_LOGI(TAG, "Connect to %s and open http://192.168.4.1/", AP_SSID);
}
