#include <stdlib.h>
#define TAG "CURRENT_AP"
#define AP_SSID "TCU-CURRENT"
#define AP_PASSWORD "tcu-current"
#define CURRENT_CHANNEL ADC_CHANNEL_4
static adc_oneshot_unit_handle_t adc_unit; static adc_cali_handle_t adc_cali; static bool adc_cali_valid;
static float vref_mv=1650.0f,sense_gain=10.0f,shunt_ohm=0.00025f,scale=0.97f,offset_a=0.0f;
static esp_err_t read_current(float *out,float *raw,float *mv,int *count){int sum=0;for(int i=0;i<64;i++){int x;if(adc_oneshot_read(adc_unit,CURRENT_CHANNEL,&x)!=ESP_OK)return ESP_FAIL;sum+=x;}*count=sum/64;if(adc_cali_valid){int m;if(adc_cali_raw_to_voltage(adc_cali,*count,&m)!=ESP_OK)return ESP_FAIL;*mv=(float)m;}else *mv=(float)*count*3100.0f/4095.0f;*raw=(*mv-vref_mv)/(sense_gain*shunt_ohm*1000.0f);*out=*raw*scale+offset_a;return ESP_OK;}
static esp_err_t root(httpd_req_t *r){const char *p="<html><head><meta http-equiv=\"refresh\" content=\"1\"><meta name=\"viewport\" content=\"width=device-width\"><title>TCU Current</title></head><body><h1>TCU Current</h1><h2>Open /api/current for JSON</h2><h3>Calibration</h3><form action=\"/api/calibration\"><p>Vref mV <input name=\"vref\"><button>Save</button></p><p>Gain <input name=\"gain\"><button>Save</button></p><p>Shunt ohms <input name=\"shunt\"><button>Save</button></p><p>Scale <input name=\"scale\"><button>Save</button></p></form><p><a href=\"/api/calibration?zero=1\">Zero current at no load</a></p></body></html>";httpd_resp_set_type(r,"text/html");return httpd_resp_send(r,p,HTTPD_RESP_USE_STRLEN);}
static esp_err_t api(httpd_req_t *r){float c,raw,mv;int count;esp_err_t e=read_current(&c,&raw,&mv,&count);char j[256];int n=snprintf(j,sizeof(j),"{\"valid\":%s,\"current_a\":%.6f,\"raw_current_a\":%.6f,\"adc_mv\":%.3f,\"raw_adc\":%d,\"offset_a\":%.6f}",e==ESP_OK?"true":"false",c,raw,mv,count,offset_a);httpd_resp_set_type(r,"application/json");return httpd_resp_send(r,j,n);}
static esp_err_t cal(httpd_req_t *r){char q[128],v[32];if(httpd_req_get_url_query_str(r,q,sizeof(q))==ESP_OK){if(httpd_query_key_value(q,"vref",v,sizeof(v))==ESP_OK)vref_mv=strtof(v,0);if(httpd_query_key_value(q,"gain",v,sizeof(v))==ESP_OK)sense_gain=strtof(v,0);if(httpd_query_key_value(q,"shunt",v,sizeof(v))==ESP_OK)shunt_ohm=strtof(v,0);if(httpd_query_key_value(q,"scale",v,sizeof(v))==ESP_OK)scale=strtof(v,0);if(httpd_query_key_value(q,"zero",v,sizeof(v))==ESP_OK){float c,raw,mv;int count;if(read_current(&c,&raw,&mv,&count)==ESP_OK)offset_a=-raw*scale;}}httpd_resp_set_type(r,"application/json");return httpd_resp_sendstr(r,"{\"saved\":true}");}
void app_main(void){ESP_ERROR_CHECK(nvs_flash_init());adc_oneshot_unit_init_cfg_t u={.unit_id=ADC_UNIT_1,.ulp_mode=ADC_ULP_MODE_DISABLE};ESP_ERROR_CHECK(adc_oneshot_new_unit(&u,&adc_unit));adc_oneshot_chan_cfg_t c={.atten=ADC_ATTEN_DB_12,.bitwidth=ADC_BITWIDTH_DEFAULT};ESP_ERROR_CHECK(adc_oneshot_config_channel(adc_unit,CURRENT_CHANNEL,&c));adc_cali_curve_fitting_config_t f={.unit_id=ADC_UNIT_1,.atten=ADC_ATTEN_DB_12,.bitwidth=ADC_BITWIDTH_DEFAULT};adc_cali_valid=adc_cali_create_scheme_curve_fitting(&f,&adc_cali)==ESP_OK;ESP_ERROR_CHECK(esp_netif_init());ESP_ERROR_CHECK(esp_event_loop_create_default());esp_netif_create_default_wifi_ap();wifi_init_config_t w=WIFI_INIT_CONFIG_DEFAULT();ESP_ERROR_CHECK(esp_wifi_init(&w));wifi_config_t a={0};memcpy(a.ap.ssid,AP_SSID,sizeof(AP_SSID)-1);memcpy(a.ap.password,AP_PASSWORD,sizeof(AP_PASSWORD)-1);a.ap.ssid_len=sizeof(AP_SSID)-1;a.ap.max_connection=4;a.ap.authmode=WIFI_AUTH_WPA2_PSK;ESP_ERROR_CHECK(esp_wifi_set_mode(WIFI_MODE_AP));ESP_ERROR_CHECK(esp_wifi_set_config(WIFI_IF_AP,&a));ESP_ERROR_CHECK(esp_wifi_start());httpd_config_t hc=HTTPD_DEFAULT_CONFIG();httpd_handle_t s;ESP_ERROR_CHECK(httpd_start(&s,&hc));httpd_uri_t x={.uri="/",.method=HTTP_GET,.handler=root};httpd_uri_t y={.uri="/api/current",.method=HTTP_GET,.handler=api};httpd_uri_t z={.uri="/api/calibration",.method=HTTP_GET,.handler=cal};ESP_ERROR_CHECK(httpd_register_uri_handler(s,&x));ESP_ERROR_CHECK(httpd_register_uri_handler(s,&y));ESP_ERROR_CHECK(httpd_register_uri_handler(s,&z));ESP_LOGI(TAG,"AP ready: http://192.168.4.1/");}
"@; Set-Content -LiteralPath "main\main.c" -Value $c -Encoding ascii; Set-Content -LiteralPath "main\CMakeLists.txt" -Value "idf_component_register(SRCS `"main.c`" INCLUDE_DIRS `".`" PRIV_REQUIRES esp_wifi esp_event esp_netif esp_http_server nvs_flash esp_adc)" -Encoding ascii; Set-Content -LiteralPath "CMakeLists.txt" -Value "cmake_minimum_required(VERSION 3.16)`ninclude(`$ENV{IDF_PATH}/tools/cmake/project.cmake)`nproject(TCU_Current_AP)" -Encoding ascii
